cd /tmp && python3 << 'EOF'
import zipfile, re

src = "/home/kfk/my/Temp/2D Browser Runner BI бриф на прорахунок.docx"
z = zipfile.ZipFile(src)
num_xml = z.read("word/numbering.xml").decode("utf-8")

# Map numId -> abstractNumId
num_to_abs = {}
for m in re.finditer(r'<w:num w:numId="(\d+)"[^>]*>\s*<w:abstractNumId w:val="(\d+)"', num_xml, re.S):
    num_to_abs[m.group(1)] = m.group(2)

# Map abstractNumId -> {ilvl: numFmt}
abs_fmt = {}
for ab in re.finditer(r'<w:abstractNum[^>]*w:abstractNumId="(\d+)"(.*?)</w:abstractNum>', num_xml, re.S):
    aid, body = ab.group(1), ab.group(2)
    lvls = {}
    for lv in re.finditer(r'<w:lvl[^>]*w:ilvl="(\d+)"[^>]*>(.*?)</w:lvl>', body, re.S):
        ilvl = lv.group(1)
        fmt = re.search(r'<w:numFmt w:val="([^"]+)"', lv.group(2))
        lvls[ilvl] = fmt.group(1) if fmt else "?"
    abs_fmt[aid] = lvls

print("numId -> format per level (numIds used in doc: 1,2,3,4,5)")
for nid in ["1","2","3","4","5"]:
    aid = num_to_abs.get(nid, "?")
    fmts = abs_fmt.get(aid, {})
    pretty = {k: fmts[k] for k in sorted(fmts) if int(k) <= 2}
    print(f"  numId={nid} (abstractNum={aid}): {pretty}")

# Now map to where each is used (from the paragraph map)
print("\nWhere each numId is used:")
uses = {
 "4": "Section 1 bullets (Бренд/Продукт/Формат/Мета) — top level",
 "1": "Section 2: Платформа/Жанр/геймплей(0), Вибір/Раунд(1), Збір/Броня/Перешкоди(2)",
 "2": "Section 3A bullets (Персонажі/Вороги/Бекграунд/UI-UX)",
 "5": "Section 3Б bullets (Движок/Аналітика/CTA)",
 "3": "Section 4: Оцінка вартості/термінів/Стек(0) + sub-items(1)",
}
for k,v in uses.items():
    print(f"  numId={k}: {v}")
EOF

